{
  "name": "subagent-live-status-plugin",
  "version": "1.4.6",
  "description": "Shows the model used by currently running subagents in the OpenCode TUI",
  "type": "module",
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --test \"src/**/*.test.ts\""
  },
  "engines": {
    "node": ">=22.6.0"
  },
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src/index.ts",
    "src/tui.tsx",
    "src/lib/collect.ts"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "subagent"
  ],
  "license": "MIT",
  "dependencies": {
    "@opencode/plugin": "^2.2.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/client": "^2.2.0",
    "@opencode/theme": "^2.2.0",
    "@opentui/core": "^0.7.0",
    "@opentui/solid": "^0.7.0",
    "solid-js": "^1.9.0",
    "typescript": "^5.6.0"
  }
}
